#!/usr/bin/env python3
"""Regenerate THIRD-PARTY-NOTICES.md for everything vendored into `dist/`.

`dist/` is no longer committed, but this file stays: the bundles were committed up to
d65db17 and remain reachable in git history, so a clone still carries them and the
attribution has to travel with the repository. It also documents what a local
`vendor_assets.py` build puts on disk. MIT, BSD-3-Clause and Apache-2.0 all require the
licence text to accompany the copy, and generating rather than hand-maintaining the list
means a re-vendor that pulls in a new transitive dependency cannot silently drop its
attribution.

The component list is DERIVED, not curated:
  * esbuild leaves `// node_modules/<pkg>/...` markers in the two Mosaic bundles, so the
    exact set of inlined packages is readable straight off the shipped artifact.
  * The DuckDB-WASM and Perspective files are copied verbatim by build.mjs, so their
    packages are added explicitly.

Run after `npm install` + `build.mjs` (needs node_modules for the licence texts):
    python3 benchmarks/probes/vendor/gen_notices.py
"""

from __future__ import annotations

import json
import re
from pathlib import Path

VENDOR = Path(__file__).resolve().parent
DIST = VENDOR / "dist"
NM = VENDOR / "node_modules"
FALLBACK = VENDOR / "licenses-fallback"
OUT = VENDOR.parents[2] / "THIRD-PARTY-NOTICES.md"

# Copied verbatim into dist/ by build.mjs steps 2 and 3 — no esbuild marker to read.
VERBATIM = [
    "@duckdb/duckdb-wasm",
    "@perspective-dev/client",
    "@perspective-dev/server",
    "@perspective-dev/viewer",
    "@perspective-dev/viewer-charts",
]
BUNDLES = ["mosaic_wasm.js", "mosaic_server_vgplot.js"]
MARKER = re.compile(r"^// node_modules/((?:@[^/\s]+/)?[^/\s]+)/", re.M)


def bundled() -> set[str]:
    found: set[str] = set()
    for name in BUNDLES:
        path = DIST / name
        if path.exists():
            found |= set(MARKER.findall(path.read_text(errors="ignore")))
    return found


def licence_text(pkg: str) -> tuple[str, str, str]:
    """(version, spdx, full text) for one package."""
    meta = NM / pkg / "package.json"
    if not meta.exists():
        return ("?", "?", "")
    data = json.loads(meta.read_text())
    spdx = data.get("license") or "see package"
    if isinstance(spdx, list):  # legacy `licenses: [{type: ...}]`
        spdx = " OR ".join(x.get("type", "?") for x in spdx)
    text = ""
    for cand in sorted((NM / pkg).glob("LICENSE*")) + sorted((NM / pkg).glob("licence*")):
        if cand.is_file():
            text = cand.read_text(errors="ignore").strip()
            break
    if not text:
        # Some tarballs ship no licence file (duckdb-wasm). The text then comes from the
        # upstream repo, committed under licences-fallback/ — see its README.
        fallback = FALLBACK / (pkg.replace("/", "__") + ".txt")
        if fallback.exists():
            text = fallback.read_text(errors="ignore").strip()
    return (str(data.get("version", "?")), str(spdx), text)


def main() -> None:
    pkgs = sorted(bundled() | set(VERBATIM))
    rows, bodies, missing = [], [], []
    for pkg in pkgs:
        version, spdx, text = licence_text(pkg)
        how = "copied verbatim" if pkg in VERBATIM else "bundled"
        rows.append(f"| `{pkg}` | {version} | {spdx} | {how} |")
        if text:
            bodies.append(f"### {pkg} {version}\n\n```\n{text}\n```\n")
        else:
            missing.append(pkg)

    OUT.write_text(
        "# Third-party notices\n\n"
        "`benchmarks/probes/vendor/dist/` holds the engine bundles under test. It is not\n"
        "committed as of d65db17, but earlier commits carried it and those objects remain\n"
        "reachable in git history, so a clone of this repository still distributes them.\n"
        "The same components are what `benchmarks/vendor_assets.py` builds locally. Each is\n"
        "used unmodified under its own licence and is reproduced here as those licences\n"
        "require. FlexViz Benchmarks itself is Apache-2.0 (see `LICENSE`).\n\n"
        "This file is generated by `benchmarks/probes/vendor/gen_notices.py` from the\n"
        "esbuild input markers in the shipped bundles plus the verbatim-copied packages —\n"
        "so it cannot drift from what is actually distributed. Versions and SHA-256 hashes\n"
        "of the distributed files are pinned in `benchmarks/probes/vendor/manifest.json`.\n\n"
        f"{len(pkgs)} components.\n\n"
        "| Component | Version | Licence | In dist/ |\n|---|---|---|---|\n"
        + "\n".join(rows)
        + "\n\n"
        + ("> Licence text not found in the package for: "
           + ", ".join(f"`{m}`" for m in missing)
           + ". Refer to the upstream project.\n\n" if missing else "")
        + "---\n\n## Licence texts\n\n"
        + "\n".join(bodies)
    )
    print(f"wrote {OUT.relative_to(OUT.parents[1])}: {len(pkgs)} components, {len(missing)} missing text")


if __name__ == "__main__":
    main()
